input.command:
python3 - <<'EOF'
import json, pathlib
from collections import Counter, defaultdict

# The screen_output doesn't have raw trial data. Let me look at what NCT IDs
# appear in Jan 15 snapshot's catalyst data, then cross-check their first_posted
# dates in both cache files

p = pathlib.Path('/mnt/c/Projects/biotech_screener/biotech-screener/data/snapshots/2026-01-15/screen_output.json')
data = json.loads(p.read_text())

# Collect all NCT IDs referenced in the Jan 15 snapshot
nct_ids = set()
def collect_nct(obj, depth=0):
    if depth > 8: return
    if isinstance(obj, dict):
        for k, v in obj.items():
            if k == 'nct_id' and isinstance(v, str):
                nct_ids.add(v)
            else:
                collect_nct(v, depth+1)
    elif isinstance(obj, list):
        for item in obj:
            collect_nct(item, depth+1)

collect_nct(data)
print(f"Unique NCT IDs in Jan 15 snapshot: {len(nct_ids)}")

# Now check: in the PIT-UNSAFE pit_archives file, are any of these NCT IDs
# from trials with first_posted > 2026-01-15?
archive = json.loads(pathlib.Path('/mnt/c/Projects/biotech_screener/biotech-screener/data/pit_archives/2026-01-15/trial_records.json').read_text())
archive_by_nct = {r['nct_id']: r for r in archive if r.get('nct_id')}

violations = []
for nct in nct_ids:
    if nct in archive_by_nct:
        fp = str(archive_by_nct[nct].get('first_posted',''))[:10]
        if fp > '2026-01-15':
            violations.append((nct, fp))

print(f"NCT IDs used in snapshot with first_posted > 2026-01-15: {len(violations)}")
if violations:
    print("  VIOLATIONS (would be PIT-unsafe if pit_archives were the source):")
    for nct, fp in violations[:10]:
        print(f"    {nct}  first_posted={fp}")
else:
    print("  Zero violations — consistent with PIT-safe source being used")

# Now check against the PIT-SAFE cache/ctgov file
cache = json.loads(pathlib.Path('/mnt/c/Projects/biotech_screener/biotech-screener/cache/ctgov/trial_records_2026-01-15.json').read_text())
cache_ncts = {r['nct_id'] for r in cache if r.get('nct_id')}
in_cache = nct_ids & cache_ncts
in_archive_only = nct_ids - cache_ncts
print(f"\nNCTs also in cache/ctgov: {len(in_cache)}")
print(f"NCTs in snapshot but NOT in cache/ctgov: {len(in_archive_only)}")
if in_archive_only:
    print("  Sample (may be newer trials):", list(in_archive_only)[:5])
    # Check their first_posted dates
    for nct in list(in_archive_only)[:5]:
        if nct in archive_by_nct:
            fp = archive_by_nct[nct].get('first_posted','N/A')
            print(f"    {nct}: first_posted={fp}")
EOF

