                    and (d/'rankings.csv').exists()])

issues = []

for snap_dir in canonical:
    date = snap_dir.name
    try:
        df = pd.read_csv(snap_dir / 'rankings.csv')
    except Exception as e:
        issues.append(f"{date}  READ_ERROR: {e}")
        continue

    elig = df[df['eligible'] == 1]
    ranked = df[df['actionable_rank'].notna()]

    # 1. Ineligible tickers must have no actionable_rank
    inelig_with_rank = df[(df['eligible'] != 1) & df['actionable_rank'].notna()]
    if len(inelig_with_rank):
        issues.append(f"{date}  INELIG_RANKED: {len(inelig_with_rank)} ineligible tickers have actionable_rank")

    # 2. Ranks must be 1..N with no gaps or duplicates
    if len(ranked):
        ranks = ranked['actionable_rank'].dropna().astype(int).sort_values()
        expected = pd.Series(range(1, len(ranks)+1))
        if not (ranks.values == expected.values).all():
            issues.append(f"{date}  RANK_GAPS: ranks not contiguous 1..{len(ranks)}")

    # 3. v1.4+: actionable_rank must equal rank(final_score) descending
    if 'final_score' in df.columns and ranked['final_score'].notna().all():
        implied = elig['final_score'].rank(ascending=False, method='min')
        match = (elig['actionable_rank'].values == implied.values).mean()
        if match < 0.99:
            issues.append(f"{date}  RANK_MISMATCH: rank(final_score) match={match:.1%}")

    # 4. de_sort_total_adj == sum(de_sort_contrib_*) for rows where present
    contrib_cols = [c for c in df.columns if c.startswith('de_sort_contrib_')]
    if contrib_cols and 'de_sort_total_adj' in df.columns:
        mask = df['de_sort_total_adj'].notna() & df[contrib_cols].notna().all(axis=1)
        if mask.sum() > 0:
            diff = (df.loc[mask, 'de_sort_total_adj'] - df.loc[mask, contrib_cols].sum(axis=1)).abs()
            if diff.max() > 0.001:
                issues.append(f"{date}  DESUM_ERR: max diff={diff.max():.4f}")

    # 5. final_score = selector_score + ranker_adjustment
    for col in ['selector_score', 'ranker_adjustment', 'final_score']:
        pass  # only check where all three present
    if all(c in df.columns for c in ['selector_score','ranker_adjustment','final_score']):
        mask = df[['selector_score','ranker_adjustment','final_score']].notna().all(axis=1)
        if mask.sum() > 0:
            diff = (df.loc[mask,'final_score'] -
                    (df.loc[mask,'selector_score'] + df.loc[mask,'ranker_adjustment'])).abs()
            if diff.max() > 0.001:
                issues.append(f"{date}  FINALSCORE_ERR: max diff={diff.max():.4f}")

    # 6. Score monotonicity: rank 1 must have highest final_score (or selector_score)
    score_col = 'final_score' if 'final_score' in df.columns else 'selector_score'
    if score_col in df.columns and ranked[score_col].notna().all():
        r1_score = ranked.loc[ranked['actionable_rank']==1, score_col].values
        rN_score = ranked.loc[ranked['actionable_rank']==ranked['actionable_rank'].max(), score_col].values
        if len(r1_score) and len(rN_score) and r1_score[0] < rN_score[0]:
            issues.append(f"{date}  MONOTONE_ERR: rank1 score < rankN score")

    # 7. Sanity: at least 10 eligible tickers
    if len(elig) < 10:
        issues.append(f"{date}  LOW_ELIG: only {len(elig)} eligible tickers")

print(f"Snapshots checked: {len(canonical)}")
print(f"Issues found: {len(issues)}")
if issues:
    for i in issues:
        print(f"  {i}")
else:
    print("  All checks passed.")
