                    and (d/'rankings.csv').exists()])

issues = []

for snap_dir in canonical:
    date = snap_dir.name
    try:
        df = pd.read_csv(snap_dir / 'rankings.csv')
    except Exception:
        continue

    # ── Core rank integrity ──────────────────────────────────────────────────
    ranked = df[df['actionable_rank'].notna()]

    # No gaps/dupes in rank sequence
    if len(ranked):
        ranks = ranked['actionable_rank'].dropna().astype(int).sort_values().values
        if not (ranks == np.arange(1, len(ranks)+1)).all():
            issues.append(f"{date}  RANK_GAPS")

    # Ineligible tickers must not be ranked
    if ((df['eligible'] != 1) & df['actionable_rank'].notna()).any():
        issues.append(f"{date}  INELIG_RANKED")

    # ── v1.4+ formula check (ranker_active=1 only) ───────────────────────────
    if all(c in df.columns for c in ['final_score','selector_score','ranker_adjustment','ranker_active']):
        active = df[df['ranker_active'] == 1]
        if len(active):
            diff = (active['final_score'] -
                    (active['selector_score'] + active['ranker_adjustment'])).abs()
            if diff.max() > 0.0001:
                issues.append(f"{date}  ACTIVE_SCORE_ERR  max_diff={diff.max():.6f}")

    # ── v1.4+: actionable_rank == rank(final_score) descending ───────────────
    if 'final_score' in df.columns:
        elig = df[df['actionable_rank'].notna()]
        if len(elig) and elig['final_score'].notna().all():
            implied = elig['final_score'].rank(ascending=False, method='min')
            if not (elig['actionable_rank'].values == implied.values).all():
                match = (elig['actionable_rank'].values == implied.values).mean()
                issues.append(f"{date}  RANK_MISMATCH  match={match:.1%}")

    # ── de_sort_total_adj = sum(contribs) ────────────────────────────────────
    contrib_cols = [c for c in df.columns if c.startswith('de_sort_contrib_')]
    if contrib_cols and 'de_sort_total_adj' in df.columns:
        mask = df['de_sort_total_adj'].notna() & df[contrib_cols].notna().all(axis=1)
        if mask.sum() > 0:
            diff = (df.loc[mask,'de_sort_total_adj'] -
                    df.loc[mask, contrib_cols].sum(axis=1)).abs()
            if diff.max() > 0.001:
                issues.append(f"{date}  DESUM_ERR  max={diff.max():.4f}")

    # ── Score monotonicity on ranked set ─────────────────────────────────────
    if 'final_score' in df.columns:
        r = ranked[['actionable_rank','final_score']].dropna().sort_values('actionable_rank')
        if len(r) > 1 and not r['final_score'].is_monotonic_decreasing:
            issues.append(f"{date}  MONOTONE_ERR")

print(f"Snapshots: {len(canonical)}")
print(f"Issues: {len(issues)}")
for i in issues:
    print(f"  {i}")
if not issues:
    print("  All checks passed.")
