            'date': snap_dir.name,
            'rank': r['actionable_rank'] if pd.notna(r['actionable_rank']) else None,
            'eligible': r.get('eligible'),
        })
    else:
        rows.append({'date': snap_dir.name, 'rank': None, 'eligible': None})

df = pd.DataFrame(rows).sort_values('date')

# Show from May 7 onwards
print("INSM rank from May 7 to end:")
for _, r in df[df['date'] >= '2026-05-07'].iterrows():
    rank_str = f"{int(r['rank']):>4}" if pd.notna(r['rank']) else '  NR'
    print(f"  {r['date']}  rank={rank_str}  eligible={r['eligible']}")
