# TestCounterfactualRank
# ---------------------------------------------------------------------------

class TestCounterfactualRank:
    def test_drug_drops_out_of_top30_without_financial(self, profiles):
        """If DRUG's financial contribution is zeroed, counterfactual rank > 30."""
        cf = profiles["DRUG"].get("mean_cf_rank_zero_fi")
        assert cf is not None
